fn fibonacci() -> impl Iterator<Item = u64> {
    std::iter::successors(Some((0u64, 1u64)), |&(a, b)| Some((b, a + b)))
        .map(|(a, _)| a)
}

for n in fibonacci().take(10) {     // exactly ten steps
    println!("{n}");
}

